// utils/composite/{composite}/interfaces.ts

// Interface commune — feuilles et groupes l'implémentent
export interface {Composite}Component {
  label: string
  // Méthode commune traitée identiquement pour feuilles et groupes
  render(): {Composite}Rendered
  isLeaf(): boolean
}

// Format de rendu final
export interface {Composite}Rendered {
  label:     string
  // Ajoute ici les propriétés de la feuille (href, icon, etc.)
  children?: {Composite}Rendered[]
}

// utils/composite/{composite}/{Composite}Tree.ts
import type { {Composite}Component, {Composite}Rendered } from './interfaces'

// Feuille — élément simple sans enfants
export class {Composite}Leaf implements {Composite}Component {
  constructor(
    public label: string,
    // Ajoute ici les propriétés spécifiques à la feuille
    // Exemple : public href: string, public icon?: string
  ) {}

  isLeaf(): boolean {
    return true
  }

  render(): {Composite}Rendered {
    return {
      label: this.label,
      // Ajoute ici le rendu de la feuille
    }
  }
}

// Groupe — contient des enfants (feuilles ou autres groupes)
export class {Composite}Group implements {Composite}Component {
  private children: {Composite}Component[] = []

  constructor(
    public label: string,
    // Ajoute ici les propriétés du groupe
  ) {}

  add(item: {Composite}Component): this {
    this.children.push(item)
    return this
  }

  remove(label: string): this {
    this.children = this.children.filter(c => c.label !== label)
    return this
  }

  isLeaf(): boolean {
    return false
  }

  // render() est récursif — traverse l'arbre transparentement
  render(): {Composite}Rendered {
    return {
      label:    this.label,
      children: this.children.map(c => c.render())
    }
  }
}

// Builder — construit l'arbre sans `new` direct dans les composables
export class {Composite}Builder {
  private items: {Composite}Component[] = []

  addLeaf(
    label: string,
    // Ajoute ici les paramètres de la feuille
  ): this {
    this.items.push(new {Composite}Leaf(label))
    return this
  }

  addGroup(
    label: string,
    build?: (group: {Composite}Group) => void
  ): this {
    const group = new {Composite}Group(label)
    if (build) build(group)
    this.items.push(group)
    return this
  }

  build(): {Composite}Rendered[] {
    return this.items.map(item => item.render())
  }
}

export const create{Composite} = (): {Composite}Builder => new {Composite}Builder()

// composables/use{Composite}.ts
import { create{Composite} } from '~/utils/composite/{composite}/{Composite}Tree'
import type { {Composite}Rendered } from '~/utils/composite/{composite}/interfaces'

export const use{Composite} = () => {
  const tree = computed<{Composite}Rendered[]>(() => {
    const builder = create{Composite}()

    // Ajoute ici la construction dynamique de l'arbre
    // Exemple pour un menu :
    // builder
    //   .addLeaf('Accueil', '/', 'mdi-home')
    //   .addGroup('Section', 'mdi-folder', group => {
    //     group.add(new {Composite}Leaf('Item A', '/a'))
    //     group.add(new {Composite}Leaf('Item B', '/b'))
