    return builder.build()
  })

  return { tree }
}

// tests/utils/composite/{composite}/{Composite}Tree.spec.ts
import { describe, it, expect } from 'vitest'
import {
  {Composite}Leaf,
  {Composite}Group,
  create{Composite}
} from '~/utils/composite/{composite}/{Composite}Tree'

describe('{Composite}Tree', () => {

  describe('{Composite}Leaf', () => {
    it('isLeaf() retourne true', () => {
      const leaf = new {Composite}Leaf('Item')
      expect(leaf.isLeaf()).toBe(true)
    })

    it('render() retourne le bon label', () => {
      const leaf = new {Composite}Leaf('Item')
      expect(leaf.render().label).toBe('Item')
    })

    it('render() ne retourne pas de children', () => {
      const leaf = new {Composite}Leaf('Item')
      expect(leaf.render().children).toBeUndefined()
    })
  })

  describe('{Composite}Group', () => {
    it('isLeaf() retourne false', () => {
      const group = new {Composite}Group('Groupe')
      expect(group.isLeaf()).toBe(false)
    })

    it('render() retourne les children', () => {
      const group = new {Composite}Group('Groupe')
      group.add(new {Composite}Leaf('Enfant A'))
      group.add(new {Composite}Leaf('Enfant B'))
      const rendered = group.render()
      expect(rendered.children).toHaveLength(2)
    })

    it('remove() retire un enfant par label', () => {
      const group = new {Composite}Group('Groupe')
      group.add(new {Composite}Leaf('A')).add(new {Composite}Leaf('B'))
      group.remove('A')
      expect(group.render().children).toHaveLength(1)
    })

    it('render() est récursif — group dans group', () => {
      const root  = new {Composite}Group('Root')
      const child = new {Composite}Group('Child')
      child.add(new {Composite}Leaf('Deep'))
      root.add(child)
      const rendered = root.render()
      expect(rendered.children?.[0].children?.[0].label).toBe('Deep')
    })
  })

  describe('{Composite}Builder', () => {
    it('build() retourne un tableau de rendus', () => {
      const result = create{Composite}()
        .addLeaf('Item')
        .build()
      expect(result).toHaveLength(1)
    })

    it('feuilles et groupes sont traités identiquement par build()', () => {
      const result = create{Composite}()
        .addLeaf('Feuille')
        .addGroup('Groupe')
        .build()
      expect(result).toHaveLength(2)
      result.forEach(item => expect(item.label).toBeDefined())
    })
  })

})
